-- Offers cell (offers), generated by solo-cell-kit from cell.yaml.
-- Every row belongs to a workspace and is visible only while the transaction
-- is bound to it (app.workspace_id). Do not edit once applied; add a new migration.

CREATE SCHEMA offers;

CREATE FUNCTION offers.current_workspace() RETURNS uuid
LANGUAGE sql STABLE AS $$
    SELECT nullif(current_setting('app.workspace_id', true), '')::uuid
$$;

CREATE TABLE offers.offers (
    workspace_id             uuid NOT NULL,
    id                       bigint GENERATED BY DEFAULT AS IDENTITY (START WITH 1000000),
    legacy_id                bigint,
    slug                     text NOT NULL CHECK (length(slug) <= 80 AND length(slug) >= 1),
    title                    text NOT NULL CHECK (length(title) <= 200 AND length(title) >= 1),
    stream                   text NOT NULL CHECK (length(stream) <= 80 AND length(stream) >= 1),
    kind                     text NOT NULL DEFAULT 'productized_service' CHECK (kind IN ('service', 'productized_service', 'digital_product', 'subscription', 'course')),
    status                   text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'priced', 'listed', 'paused', 'retired')),
    owner_scope              text NOT NULL DEFAULT 'solo_empire' CHECK (owner_scope IN ('personal', 'solo_empire', 'venture', 'client', 'shared')),
    summary                  text,
    deliverables             text,
    delivery_days            integer CHECK (delivery_days IS NULL OR (delivery_days >= 0)),
    terms_ref                text,
    project_id               bigint,
    goal_id                  bigint,
    source_ref               text,
    notes                    text,
    version                  bigint NOT NULL DEFAULT 1,
    created_at               timestamptz NOT NULL DEFAULT now(),
    updated_at               timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, id),
    UNIQUE (workspace_id, slug)
);
CREATE UNIQUE INDEX offers_legacy ON offers.offers (workspace_id, legacy_id) WHERE legacy_id IS NOT NULL;
CREATE INDEX offers_kind ON offers.offers (workspace_id, kind);
CREATE INDEX offers_owner_scope ON offers.offers (workspace_id, owner_scope);
CREATE INDEX offers_status ON offers.offers (workspace_id, status);
CREATE INDEX offers_stream ON offers.offers (workspace_id, stream);

CREATE TABLE offers.offer_prices (
    workspace_id             uuid NOT NULL,
    id                       bigint GENERATED BY DEFAULT AS IDENTITY (START WITH 1000000),
    legacy_id                bigint,
    offer_id                 bigint NOT NULL,
    tier                     text NOT NULL CHECK (length(tier) <= 80 AND length(tier) >= 1),
    amount                   double precision NOT NULL CHECK (amount >= 0),
    currency                 text NOT NULL DEFAULT 'THB' CHECK (length(currency) <= 12),
    billing_interval         text NOT NULL DEFAULT 'one_time' CHECK (billing_interval IN ('one_time', 'monthly', 'quarterly', 'yearly')),
    provider                 text NOT NULL DEFAULT 'stripe' CHECK (length(provider) <= 40),
    provider_ref             text CHECK (provider_ref IS NULL OR (length(provider_ref) <= 200)),
    payment_link_url         text CHECK (payment_link_url IS NULL OR (length(payment_link_url) <= 500)),
    active                   boolean NOT NULL DEFAULT true,
    valid_from               date,
    valid_to                 date,
    notes                    text,
    version                  bigint NOT NULL DEFAULT 1,
    created_at               timestamptz NOT NULL DEFAULT now(),
    updated_at               timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, id),
    UNIQUE (workspace_id, offer_id, tier, currency, billing_interval),
    FOREIGN KEY (workspace_id, offer_id) REFERENCES offers.offers (workspace_id, id)
);
CREATE UNIQUE INDEX offer_prices_legacy ON offers.offer_prices (workspace_id, legacy_id) WHERE legacy_id IS NOT NULL;
CREATE INDEX offer_prices_active ON offers.offer_prices (workspace_id, active);
CREATE INDEX offer_prices_billing_interval ON offers.offer_prices (workspace_id, billing_interval);
CREATE INDEX offer_prices_currency ON offers.offer_prices (workspace_id, currency);
CREATE INDEX offer_prices_offer_id ON offers.offer_prices (workspace_id, offer_id);

CREATE TABLE offers.offer_listings (
    workspace_id             uuid NOT NULL,
    id                       bigint GENERATED BY DEFAULT AS IDENTITY (START WITH 1000000),
    legacy_id                bigint,
    offer_id                 bigint NOT NULL,
    channel                  text NOT NULL CHECK (length(channel) <= 80 AND length(channel) >= 1),
    url                      text CHECK (url IS NULL OR (length(url) <= 500)),
    status                   text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'live', 'paused', 'removed')),
    listed_on                date,
    removed_on               date,
    notes                    text,
    version                  bigint NOT NULL DEFAULT 1,
    created_at               timestamptz NOT NULL DEFAULT now(),
    updated_at               timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, id),
    UNIQUE (workspace_id, offer_id, channel),
    FOREIGN KEY (workspace_id, offer_id) REFERENCES offers.offers (workspace_id, id)
);
CREATE UNIQUE INDEX offer_listings_legacy ON offers.offer_listings (workspace_id, legacy_id) WHERE legacy_id IS NOT NULL;
CREATE INDEX offer_listings_channel ON offers.offer_listings (workspace_id, channel);
CREATE INDEX offer_listings_offer_id ON offers.offer_listings (workspace_id, offer_id);
CREATE INDEX offer_listings_status ON offers.offer_listings (workspace_id, status);

-- Idempotent creates: a key reserves the record id before the platform execution starts.
CREATE TABLE offers.create_keys (
    workspace_id uuid NOT NULL,
    actor        uuid NOT NULL,
    kind         text NOT NULL CHECK (kind IN ('offer', 'offer-price', 'offer-listing')),
    key          text NOT NULL CHECK (length(key) BETWEEN 8 AND 200),
    record_id    bigint NOT NULL,
    created_at   timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, actor, kind, key)
);

-- Graph events, written in the same transaction as the change (at-least-once delivery).
CREATE TABLE offers.outbox (
    id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    workspace_id    uuid NOT NULL,
    type            text NOT NULL,
    subject         text NOT NULL,
    execution_id    uuid,
    classification  text NOT NULL DEFAULT 'confidential',
    payload         jsonb NOT NULL,
    occurred_at     timestamptz NOT NULL DEFAULT now(),
    published_at    timestamptz,
    attempts        integer NOT NULL DEFAULT 0,
    next_attempt_at timestamptz NOT NULL DEFAULT now(),
    last_error      text,
    correlation_id  text
);
CREATE INDEX outbox_pending ON offers.outbox (next_attempt_at) WHERE published_at IS NULL;

DO $$
DECLARE
    t text;
BEGIN
    FOREACH t IN ARRAY ARRAY['offers', 'offer_prices', 'offer_listings', 'create_keys', 'outbox'] LOOP
        EXECUTE format('ALTER TABLE offers.%I ENABLE ROW LEVEL SECURITY', t);
        EXECUTE format('ALTER TABLE offers.%I FORCE ROW LEVEL SECURITY', t);
        EXECUTE format('CREATE POLICY workspace_isolation ON offers.%I'
                       ' USING (workspace_id = offers.current_workspace())'
                       ' WITH CHECK (workspace_id = offers.current_workspace())', t);
    END LOOP;
END
$$;

GRANT USAGE ON SCHEMA offers TO offers_api;
GRANT EXECUTE ON FUNCTION offers.current_workspace() TO offers_api;
GRANT SELECT, INSERT, UPDATE, DELETE ON offers.offers, offers.offer_prices, offers.offer_listings TO offers_api;
GRANT USAGE ON SEQUENCE offers.offers_id_seq, offers.offer_prices_id_seq, offers.offer_listings_id_seq TO offers_api;
GRANT SELECT, INSERT ON offers.create_keys TO offers_api;
GRANT SELECT, INSERT ON offers.outbox TO offers_api;
GRANT UPDATE (execution_id, published_at, attempts, next_attempt_at, last_error) ON offers.outbox TO offers_api;

-- The publisher sweeps the outbox of one workspace per token; it reads past RLS for the outbox only.
CREATE POLICY publisher_sweep ON offers.outbox TO offers_publisher USING (true) WITH CHECK (true);
GRANT USAGE ON SCHEMA offers TO offers_publisher;
GRANT SELECT ON offers.outbox TO offers_publisher;
GRANT UPDATE (published_at, attempts, next_attempt_at, last_error) ON offers.outbox TO offers_publisher;
